keys.forEach((key, idx) => {
  const t = T[key], n = idx + 1;
  const ex = extras(n, t.ex); const id = (k, i) => ex.filter(e => e.id.startsWith(PFX[k] + '_l' + n + '_'))[i - 1].id;
  const prevExit = idx === 0 ? PREV0 : T[keys[idx - 1]].exit;
  const slides = [];
  const add = (block, stage, data, sug, tn) => { const sl = { id: 's' + String(slides.length + 1).padStart(2, '0'), stage, block, data }; if (tn) data.tnote = tn; sl.suggested_extras = sug || []; slides.push(sl); };
  add('cover', '도입', { title: t.cover[0], emoji: t.cover[1] }, [id('video', 1)]);
  add('review', '도입', { title: idx === 0 ? '지난 단원에서 배운 것, 기억나요?' : '지난 시간엔 무엇을 했나요?', content: t.review, items: prevExit.map(x => ({ q: x.q, a: x.a })), from: idx === 0 ? PREV_KEY : keys[idx - 1] }, [id('q', 1)]);
  add('motivate', '도입', { scene_title: t.mot.t, desc: t.mot.desc, question: t.mot.q, img: 'assets/photo/korean/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
  t.con.forEach((c, i) => add('concept', '전개', { fig: c.fig, title: c.title, content: c.content }, csug[i], c.tn));
  add('misconception', '전개', { title: '이런 생각, 맞을까요?', label: '자주 하는 생각', wrong: t.mis[0], right: t.mis[1], hint: t.mis[2] }, [id('x', 1), id('x', 2)], t.mis[3]);
  const bsug = [[id('tip', 3)], [id('e', 3)], [id('q', 4)]];
  t.basic.forEach((p, i) => add('basic_problem', '기본문제', problemData(p, '기본 문제 ' + '①②③'[i]), bsug[i]));
  add('leveled_problem', '기본문제', { title: '수준을 골라 풀어요', levels: t.lev }, [id('q', 5), id('game', 1)], t.levTn);
  add('offline_activity', '응용문제', { title: t.act.t, type: t.act.type, goal: t.act.goal, steps: t.act.steps, solo: t.act.solo, materials: t.act.mats, minutes: t.act.min }, [id('game', 2), id('tip', 4)], t.act.tn);
  add('real_world', '응용문제', { title: t.real[0], scenario: { icon: t.real[1], body: t.real[2] }, content: t.real[3] }, [id('real', 2), id('real', 3)]);
  add('advanced_problem', '응용문제', { title: '생각을 넓혀요', context: t.adv[0], challenge: t.adv[1], note: t.adv[2] }, [id('tip', 5)], t.adv[3]);
  add('exit_ticket', '정리', { title: '오늘 확인해요', items: t.exit, self: ['오늘 배운 것을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }, []);
  add('summary', '정리', { title: '오늘 배운 것', points: t.sum.concat(t.story), arrows: t.arrows }, [id('real', 1)]);
  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + t.self[0], '🔧 과정·기능 — ' + t.self[1], '💛 가치·태도 — ' + t.self[2]], prompts: [t.prompt] }, [id('e', 3)]);
  add('next_lesson', '정리', { title: idx === keys.length - 1 ? '이 단원을 마쳐요' : '다음 시간엔', preview: t.next, emoji: t.nextIcon }, [id('c', 1)]);
  const r = t.n.split('~').map(Number); const [a, b] = r.length === 2 ? r : [r[0], r[0]];
  LESSONS[key] = {
    meta: { grade: 5, subject: '국어', term: 2, unit: UNIT, unit_title: UT, n: a, covers: a === b ? a + '차시' : a + (b - a > 1 ? '~' : '·') + b + '차시', title: t.title, goal: t.goal.map(nm).join(' / '), std: t.std, duration_min: 40 * (b - a + 1), lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '우리 반 토의 마당', source: '2022 개정 국어 5-2 지도서 4단원(자기주도 원문 없음 — 케이티처 정본 · 토의 대화·만화·글 제재는 자체 집필)', src_key: key },
    slides, extras: ex
  };
});

const head = `/* ============================================================================
   5학년 2학기 국어 — 4단원 「의견을 조정해요」 케이티처 2세대 차시 데이터 (7차시 키 · 13차시분 × 19장)
   - 생성물: kedu/teacher/scripts/gen_g5s2_korean_u4.js 가 만든다. 손으로 고치지 말고 생성기(T 표)를 고칠 것.
   - 키: window.LESSONS["u4_l{NN}"] = 지도서 차시 번호(2·3 → u4_l02 · 4·5 → u4_l04 · 6·7 → u4_l06 · 8~10 → u4_l08 · 11·12 → u4_l11) · slug g5s2_korean.
   - 재료: 국어 5-2 지도서 4단원 — 자기주도 원문 없음(케이티처가 정본, learn.html 이 학생용 투영). 토의 대화·만화·글 제재는 자체 집필.
   - 계보: u4_l01 복습 = 3단원 마지막 차시(u3_l12) 출구 · 이후 차시 복습 = 직전 차시 출구 퀴즈.
   - 게이트: 표준/gate_g5s2_korean_u4.js
   ============================================================================ */
`;
fs.writeFileSync(OUT, head + '(function () {\n  if (!window.LESSONS) window.LESSONS = {};\n' + keys.map(k => '  window.LESSONS[' + JSON.stringify(k) + '] = ' + JSON.stringify(LESSONS[k]) + ';').join('\n') + '\n})();\n');
console.log('→', path.relative(process.cwd(), OUT), keys.length, '차시 키 ·', keys.reduce((a, k) => a + LESSONS[k].slides.length, 0), '장 ·', keys.reduce((a, k) => a + LESSONS[k].extras.length, 0), 'extras ·', keys.join(','));
